const NOTICE = { reach: 2.5, crouch: 0.14, air: 0.34, hop: 0.4, land: 0.1, cool: 2.5, look: 1.5 };
const notice = (g, lv, r, x0, y0, x1, y1) => {
  const H = g.hero, t = lv.tile, T = lv.t, m = NOTICE.reach * t, N = r.notice || (r.notice = { t: -9, was: false, seen: -9, left: false });
  const near = g.state === 'play' && !!H && H.maxX > x0 - m && H.minX < x1 + m && H.maxY > y0 - m && H.minY < y1 + m;
  if (near && !N.was && T - N.t > NOTICE.cool) N.t = T;
  if (near) { N.seen = T; N.left = H.cx < (x0 + x1) / 2; }
  N.was = near;
  const e = T - N.t, a = NOTICE.crouch, b = a + NOTICE.air, u = (e - a) / NOTICE.air, still = typeof POKE !== 'undefined' && POKE.still;
  const dy = still || e > b + NOTICE.land ? 0 : e < a ? -0.06 * t * (e / a) : e < b ? 4 * u * (1 - u) * NOTICE.hop * t : -0.06 * t * (1 - (e - b) / NOTICE.land);
  return { dy, face: T - N.seen < NOTICE.look ? N.left : null };
};
